<script setup lang="ts">
import { Connection,Cpu,Grid,Lightning,List,Monitor,MoreFilled,Refresh,Refrigerator,Search,Setting,SwitchButton,View,WindPower } from '@element-plus/icons-vue';
import { computed,onActivated,onMounted,ref,watch } from 'vue';
import { useI18n } from 'vue-i18n';
import { ElMessage } from 'element-plus';
import { useRouter } from 'vue-router';
import { ApiError } from '@/core/api/contracts';
import { fetchAllPages } from '@/core/api/pagination';
import { useAuthStore } from '@/core/auth/auth.store';
import { useRuntimeSettingsStore } from '@/core/settings/runtime-settings.store';
import { enumLabel } from '@/core/i18n/enum-labels';
import DsEmpty from '@/design-system/components/DsEmpty.vue';
import DsListPageShell from '@/design-system/components/DsListPageShell.vue';
import DsPagination from '@/design-system/components/DsPagination.vue';
import DsTag from '@/design-system/components/DsTag.vue';
import { useListPageState } from '@/design-system/composables/useListPageState';
import { deviceAssetApi,deviceAssetPermissions,deviceSystemPermissions,type DeviceAsset,type DeviceAssetListItem,type DeviceSystemType } from '@/domain/iot/assets/device-system';

const props=defineProps<{systemType:DeviceSystemType}>();
type Row=DeviceAsset&{systemId:string;systemName:string;systemMode:string;systemStatus:string;runtime:Runtime};
type Runtime={communication:'ONLINE'|'OFFLINE'|'WARNING';primary:number;secondary:number;target:number;mode:string;updatedAt:string};
const auth=useAuthStore(),router=useRouter(),runtimeSettings=useRuntimeSettingsStore();
const {t,te,locale}=useI18n();
const loading=ref(true),keyword=ref(''),status=ref(''),subtype=ref(''),viewMode=ref<'card'|'list'>('card');
const rows=ref<Row[]>([]),detail=ref<Row|null>(null),detailVisible=ref(false),tick=ref(0),selectedIds=ref<number[]>([]);
const permissions=computed(()=>deviceAssetPermissions(props.systemType));
const systemPermissions=computed(()=>deviceSystemPermissions(props.systemType));
const canExploreEdit=computed(()=>auth.canEnterAll([permissions.value.update,systemPermissions.value.update]));
const title=computed(()=>t(`deviceSystemPage.deviceAsset.title.${props.systemType}`));
const isHvac=computed(()=>props.systemType==='HVAC');
const filtered=computed(()=>rows.value.filter(row=>(!keyword.value||`${row.name} ${row.code} ${row.model||''} ${row.systemName}`.toLowerCase().includes(keyword.value.trim().toLowerCase()))&&(!status.value||row.runtime.communication===status.value)&&(!subtype.value||row.subtype===subtype.value)));
const subtypes=computed(()=>[...new Set(rows.value.map(row=>row.subtype))]);
const {page,pageSize,pagedRows}=useListPageState({rows:filtered,resetDeps:()=>[keyword.value,status.value,subtype.value]});
const stats=computed(()=>({total:rows.value.length,online:rows.value.filter(row=>row.runtime.communication==='ONLINE').length,offline:rows.value.filter(row=>row.runtime.communication==='OFFLINE').length,warning:rows.value.filter(row=>row.runtime.communication==='WARNING').length,systems:new Set(rows.value.map(row=>row.systemId)).size}));
const selectedRows=computed(()=>rows.value.filter(row=>selectedIds.value.includes(Number(row.id))));
const allVisibleSelected=computed(()=>pagedRows.value.length>0&&pagedRows.value.every(row=>selectedIds.value.includes(Number(row.id))));
function systemPath(type:DeviceSystemType){return ({HVAC:'/assets/hvac',LIGHTING:'/assets/lighting',PARKING:'/assets/parking',CHARGING:'/assets/charging-piles',SOLAR:'/assets/pv-equipment',STORAGE:'/assets/storage-equipment'} as Record<string,string>)[type];}
function labelSubtype(value:string){const key=`deviceSystemPage.subtype.${value}`;return te(key)?t(key):value;}
function systemMode(value:string){const key=`deviceSystemPage.mode.${value}`;return value&&(te(key)?t(key):value)||'--';}
function buildRuntime(asset:DeviceAsset):Runtime{const seed=Number(asset.id)*17+tick.value;const communication=asset.status!=='ACTIVE'?'OFFLINE':seed%11===0?'WARNING':seed%7===0?'OFFLINE':'ONLINE';const base=(seed%65)+18;return {communication,primary:Number((base+(seed%10)/10).toFixed(1)),secondary:Number((35+seed%51).toFixed(0)),target:Number((22+seed%5).toFixed(0)),mode:props.systemType==='HVAC'?['COOLING','FAN','AUTO'][seed%3]:'RUNNING',updatedAt:new Date().toISOString()};}
function enrich(item:DeviceAssetListItem):Row{return {...item.asset,systemId:item.systemId||'',systemName:item.systemName||'',systemMode:item.systemMode||'',systemStatus:item.systemStatus||'DISABLED',runtime:buildRuntime(item.asset)};}
function showError(error:unknown,fallback:string){ElMessage.error(error instanceof ApiError?error.message:fallback);}
async function load(){if(!auth.can(permissions.value.view))return;loading.value=true;try{const result=await fetchAllPages((page,pageSize)=>deviceAssetApi.page(props.systemType,{page,pageSize}));rows.value=result.map(enrich);}catch(error){showError(error,t('deviceSystemPage.deviceAsset.messages.loadFailed'));}finally{loading.value=false;}}
function switchView(value:'card'|'list'){viewMode.value=value;}
function openDetail(row:Row){detail.value=row;detailVisible.value=true;}
function editSystem(row:Row){if(!canExploreEdit.value||!row.systemId)return;router.push({path:systemPath(props.systemType),query:{edit:row.systemId}});}
function mockControl(row:Row,action:string){if(!auth.can(permissions.value.control))return;ElMessage.info(t('deviceSystemPage.deviceAsset.control.singleCommand',{name:row.name,action}));}
function statusTone(value:string){return value==='ONLINE'?'success':value==='WARNING'?'warning':'neutral';}
function statusLabel(value:string){return t(`deviceSystemPage.communication.${value}`);}
function primaryLabel(row:Row){if(props.systemType==='HVAC')return ['INDOOR_UNIT','FAN_COIL','AIR_HANDLING_UNIT','FRESH_AIR_UNIT'].includes(row.subtype)?`${row.runtime.primary} ℃`:`${row.runtime.primary} kW`;if(props.systemType==='PARKING')return `${row.runtime.secondary}%`;if(props.systemType==='STORAGE')return `${row.runtime.secondary}% SOC`;return `${row.runtime.primary} kW`;}
function secondaryLabel(row:Row){if(props.systemType==='HVAC')return `${t(`deviceSystemPage.deviceAsset.runtime.${row.runtime.mode}`)} · ${t('deviceSystemPage.deviceAsset.runtime.setpoint',{value:row.runtime.target})}`;return `${row.capacityValue??0} ${row.capacityUnit||''}`.trim();}
function deviceIcon(subtype:string){if(['CHILLER','OUTDOOR_UNIT','INDOOR_UNIT','FAN_COIL'].includes(subtype))return Refrigerator;if(['CHILLED_WATER_PUMP','COOLING_WATER_PUMP','COOLING_TOWER','AIR_HANDLING_UNIT','FRESH_AIR_UNIT'].includes(subtype))return WindPower;if(['DISTRIBUTION_CABINET','CONTROLLER','BMS'].includes(subtype))return Cpu;if(['LUMINAIRE','CHARGER','PV_ARRAY','INVERTER','PCS','BATTERY_CLUSTER'].includes(subtype))return Lightning;if(['BARRIER_GATE','VEHICLE_DETECTOR'].includes(subtype))return Connection;return Monitor;}
function toggleVisibleSelection(){const visibleIds=pagedRows.value.map(row=>Number(row.id));selectedIds.value=allVisibleSelected.value?selectedIds.value.filter(id=>!visibleIds.includes(id)):[...new Set([...selectedIds.value,...visibleIds])];}
function toggleSelection(id:number,checked:boolean){selectedIds.value=checked?[...new Set([...selectedIds.value,id])]:selectedIds.value.filter(item=>item!==id);}
function batchMockControl(action:string){if(!auth.can(permissions.value.control))return;if(!selectedRows.value.length){ElMessage.warning(t('deviceSystemPage.deviceAsset.control.selectFirst'));return;}ElMessage.info(t('deviceSystemPage.deviceAsset.control.command',{count:selectedRows.value.length,action}));}
onMounted(async()=>{await runtimeSettings.load();pageSize.value=runtimeSettings.pageSize;viewMode.value=runtimeSettings.deviceDefaultView==='LIST'?'list':'card';});
onActivated(load);
watch(()=>runtimeSettings.pageSize,value=>{pageSize.value=value;});
</script>

<template>
  <DsListPageShell :title="title" page-class="device-asset-page ds-domain-dense" :loading="auth.can(permissions.view) && loading">
    <template #primary-action><div class="header-actions"><el-button :icon="Refresh" :loading="loading" @click="load">{{ t('deviceSystemPage.actions.refresh') }}</el-button><el-button v-permission.preview="[permissions.update,systemPermissions.update]" :icon="Setting" :disabled="!canExploreEdit" :title="canExploreEdit?'':t('deviceSystemPage.deviceAsset.noPermission')" @click="router.push(systemPath(systemType))">{{ t('deviceSystemPage.deviceAsset.actions.manageSystem') }}</el-button></div></template>
    <section class="asset-summary"><article><span>{{ t('deviceSystemPage.deviceAsset.summary.total') }}</span><strong>{{ stats.total }}</strong></article><article><span>{{ t('deviceSystemPage.deviceAsset.summary.online') }}</span><strong class="success">{{ stats.online }}</strong></article><article><span>{{ t('deviceSystemPage.deviceAsset.summary.offline') }}</span><strong>{{ stats.offline }}</strong></article><article><span>{{ t('deviceSystemPage.deviceAsset.summary.warning') }}</span><strong class="warning">{{ stats.warning }}</strong></article><article><span>{{ t('deviceSystemPage.deviceAsset.summary.systems') }}</span><strong>{{ stats.systems }}</strong></article></section>
    <section v-if="isHvac" class="hvac-control-deck">
      <div class="selection-panel">
        <div><span>{{ t('deviceSystemPage.deviceAsset.control.console') }}</span><strong>{{ t('deviceSystemPage.deviceAsset.control.selected',{selected:selectedRows.length,total:rows.length}) }}</strong></div>
        <div class="selection-stats"><span>{{ t('deviceSystemPage.deviceAsset.control.online',{count:stats.online}) }}</span><span>{{ t('deviceSystemPage.deviceAsset.control.warning',{count:stats.warning}) }}</span><el-button link type="primary" @click="toggleVisibleSelection">{{ t(allVisibleSelected?'deviceSystemPage.deviceAsset.control.clearPage':'deviceSystemPage.deviceAsset.control.selectPage') }}</el-button></div>
      </div>
      <div v-if="auth.canShow(permissions.control)" class="command-panel" :class="{disabled:!selectedRows.length}">
        <div class="command-group"><label>{{ t('deviceSystemPage.deviceAsset.control.power') }}</label><el-button-group><el-button :icon="SwitchButton" :disabled="!auth.can(permissions.control)" @click="batchMockControl(t('deviceSystemPage.deviceAsset.control.powerOn'))">{{ t('deviceSystemPage.deviceAsset.control.powerOn') }}</el-button><el-button :disabled="!auth.can(permissions.control)" @click="batchMockControl(t('deviceSystemPage.deviceAsset.control.powerOff'))">{{ t('deviceSystemPage.deviceAsset.control.powerOff') }}</el-button></el-button-group></div>
        <div class="command-group"><label>{{ t('deviceSystemPage.deviceAsset.control.temperature') }}</label><div class="temperature-control"><el-button :disabled="!auth.can(permissions.control)" @click="batchMockControl('-1℃')">−</el-button><strong>24℃</strong><el-button :disabled="!auth.can(permissions.control)" @click="batchMockControl('+1℃')">＋</el-button></div></div>
        <div class="command-group"><label>{{ t('deviceSystemPage.deviceAsset.control.mode') }}</label><el-button-group><el-button :disabled="!auth.can(permissions.control)" @click="batchMockControl(t('deviceSystemPage.deviceAsset.control.cooling'))">{{ t('deviceSystemPage.deviceAsset.control.cooling') }}</el-button><el-button :disabled="!auth.can(permissions.control)" @click="batchMockControl(t('deviceSystemPage.deviceAsset.control.heating'))">{{ t('deviceSystemPage.deviceAsset.control.heating') }}</el-button><el-button :disabled="!auth.can(permissions.control)" @click="batchMockControl(t('deviceSystemPage.deviceAsset.control.auto'))">{{ t('deviceSystemPage.deviceAsset.control.auto') }}</el-button></el-button-group></div>
        <div class="command-group"><label>{{ t('deviceSystemPage.deviceAsset.control.fanSpeed') }}</label><el-button-group><el-button :disabled="!auth.can(permissions.control)" @click="batchMockControl(t('deviceSystemPage.deviceAsset.control.low'))">{{ t('deviceSystemPage.deviceAsset.control.low') }}</el-button><el-button :disabled="!auth.can(permissions.control)" @click="batchMockControl(t('deviceSystemPage.deviceAsset.control.medium'))">{{ t('deviceSystemPage.deviceAsset.control.medium') }}</el-button><el-button :disabled="!auth.can(permissions.control)" @click="batchMockControl(t('deviceSystemPage.deviceAsset.control.high'))">{{ t('deviceSystemPage.deviceAsset.control.high') }}</el-button></el-button-group></div>
        <div class="command-note"><DsTag type="warning">{{ t('deviceSystemPage.deviceAsset.control.simulated') }}</DsTag><span>{{ t('deviceSystemPage.deviceAsset.control.note') }}</span></div>
      </div>
      <div v-if="!auth.can(permissions.control)" class="command-readonly">{{ t('deviceSystemPage.deviceAsset.control.readonly') }}</div>
    </section>
    <section class="asset-workspace">
      <div class="asset-filters"><el-input v-model="keyword" :prefix-icon="Search" clearable :placeholder="t('deviceSystemPage.deviceAsset.filters.keyword')" /><el-select v-model="subtype" clearable :placeholder="t('deviceSystemPage.deviceAsset.filters.subtype')"><el-option v-for="item in subtypes" :key="item" :label="labelSubtype(item)" :value="item" /></el-select><el-select v-model="status" clearable :placeholder="t('deviceSystemPage.deviceAsset.filters.communication')"><el-option :label="statusLabel('ONLINE')" value="ONLINE" /><el-option :label="statusLabel('OFFLINE')" value="OFFLINE" /><el-option :label="statusLabel('WARNING')" value="WARNING" /></el-select><el-button @click="keyword='';subtype='';status=''">{{ t('deviceSystemPage.actions.reset') }}</el-button><div class="view-switch"><el-button-group><el-button :type="viewMode==='card'?'primary':'default'" :icon="Grid" @click="switchView('card')" /><el-button :type="viewMode==='list'?'primary':'default'" :icon="List" @click="switchView('list')" /></el-button-group></div></div>
      <div class="asset-content">
        <div v-if="viewMode==='card'&&pagedRows.length" class="asset-grid">
          <article v-for="row in pagedRows" :key="row.id" class="asset-card" :class="{selected:selectedIds.includes(Number(row.id))}">
            <header><el-checkbox v-if="isHvac" :model-value="selectedIds.includes(Number(row.id))" :aria-label="t('deviceSystemPage.hvacConsole.selectDevice',{name:row.name})" @change="toggleSelection(Number(row.id),Boolean($event))" /><div class="asset-title"><strong :title="row.name">{{ row.name }}</strong><small>{{ row.code }}</small></div><DsTag :type="statusTone(row.runtime.communication)">{{ statusLabel(row.runtime.communication) }}</DsTag></header>
            <div class="asset-reading"><div class="asset-icon"><el-icon><component :is="deviceIcon(row.subtype)" /></el-icon></div><div><span>{{ t('deviceSystemPage.deviceAsset.labels.telemetry') }}</span><strong>{{ primaryLabel(row) }}</strong><small>{{ secondaryLabel(row) }}</small></div></div>
            <dl><div><dt>{{ t('deviceSystemPage.deviceAsset.labels.subtype') }}</dt><dd>{{ labelSubtype(row.subtype) }}</dd></div><div><dt>{{ t('deviceSystemPage.deviceAsset.labels.system') }}</dt><dd :title="row.systemName">{{ row.systemName }}</dd></div><div><dt>{{ t('deviceSystemPage.deviceAsset.labels.systemMode') }}</dt><dd>{{ systemMode(row.systemMode) }}</dd></div><div><dt>{{ t('deviceSystemPage.deviceAsset.labels.installSpace') }}</dt><dd :title="row.installSpaceName">{{ row.installSpaceName }}</dd></div><div><dt>{{ t('deviceSystemPage.deviceAsset.labels.identifier') }}</dt><dd :title="row.access?.deviceIdentifier||'--'">{{ row.access?.deviceIdentifier||'--' }}</dd></div><div><dt>{{ t('deviceSystemPage.deviceAsset.labels.model') }}</dt><dd>{{ row.model||'--' }}</dd></div></dl>
            <footer><el-button link type="primary" :icon="View" @click="openDetail(row)">{{ t('deviceSystemPage.deviceAsset.actions.view') }}</el-button><el-button v-permission.preview="[permissions.update,systemPermissions.update]" link :icon="Setting" :disabled="!row.systemId" @click="editSystem(row)">{{ t('deviceSystemPage.deviceAsset.actions.edit') }}</el-button><el-dropdown v-if="auth.canShow(permissions.control)" trigger="click"><el-button link :icon="MoreFilled" :disabled="!auth.can(permissions.control)">{{ t('deviceSystemPage.deviceAsset.actions.mockControl') }}</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item :icon="SwitchButton" @click="mockControl(row,t('deviceSystemPage.deviceAsset.actions.startStop'))">{{ t('deviceSystemPage.deviceAsset.actions.startStop') }}</el-dropdown-item><el-dropdown-item v-if="systemType==='HVAC'" @click="mockControl(row,t('deviceSystemPage.deviceAsset.actions.modeSetpoint'))">{{ t('deviceSystemPage.deviceAsset.actions.modeSetpoint') }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></footer>
          </article>
        </div>
        <el-table v-else-if="viewMode==='list'" :data="pagedRows" table-layout="fixed"><el-table-column :label="t('deviceSystemPage.deviceAsset.labels.device')" min-width="190" show-overflow-tooltip><template #default="{row}"><div class="primary-cell"><strong>{{ row.name }}</strong><small>{{ row.code }}</small></div></template></el-table-column><el-table-column :label="t('deviceSystemPage.deviceAsset.labels.subtype')" width="126"><template #default="{row}">{{ labelSubtype(row.subtype) }}</template></el-table-column><el-table-column :label="t('deviceSystemPage.deviceAsset.labels.systemAndMode')" min-width="210" show-overflow-tooltip><template #default="{row}"><div class="primary-cell"><strong>{{ row.systemName }}</strong><small>{{ systemMode(row.systemMode) }}</small></div></template></el-table-column><el-table-column prop="installSpaceName" :label="t('deviceSystemPage.deviceAsset.labels.installSpace')" min-width="150" show-overflow-tooltip /><el-table-column :label="t('deviceSystemPage.deviceAsset.labels.telemetry')" width="150"><template #default="{row}"><div class="primary-cell"><strong>{{ primaryLabel(row) }}</strong><small>{{ secondaryLabel(row) }}</small></div></template></el-table-column><el-table-column :label="t('deviceSystemPage.deviceAsset.labels.communication')" width="92"><template #default="{row}"><DsTag :type="statusTone(row.runtime.communication)">{{ statusLabel(row.runtime.communication) }}</DsTag></template></el-table-column><el-table-column :label="t('deviceSystemPage.deviceAsset.labels.operation')" fixed="right" width="176"><template #default="{row}"><div class="ds-row-actions"><el-button link type="primary" @click="openDetail(row)">{{ t('deviceSystemPage.deviceAsset.actions.view') }}</el-button><el-button v-permission.preview="[permissions.update,systemPermissions.update]" link :disabled="!row.systemId" @click="editSystem(row)">{{ t('deviceSystemPage.actions.edit') }}</el-button><el-dropdown v-if="auth.canShow(permissions.control)" trigger="click"><el-button link :disabled="!auth.can(permissions.control)">{{ t('deviceSystemPage.actions.more') }}</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item :icon="SwitchButton" @click="mockControl(row,t('deviceSystemPage.deviceAsset.actions.startStop'))">{{ t('deviceSystemPage.deviceAsset.actions.mockControl') }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></template></el-table-column></el-table>
        <DsEmpty v-if="!loading&&!pagedRows.length" :title="t('deviceSystemPage.deviceAsset.empty.title')" :description="t('deviceSystemPage.deviceAsset.empty.description')" />
      </div>
      <footer v-if="filtered.length" class="ds-list-table-footer ds-list-table-footer--pagination-only"><DsPagination v-model:page="page" v-model:page-size="pageSize" :total="filtered.length" /></footer>
    </section>
    <template #overlays><el-drawer v-model="detailVisible" size="min(560px,96vw)" destroy-on-close><template #header><div class="drawer-title"><div><h3>{{ detail?.name }}</h3><p>{{ detail?.code }}</p></div><DsTag v-if="detail" :type="statusTone(detail.runtime.communication)">{{ statusLabel(detail.runtime.communication) }}</DsTag></div></template><template v-if="detail"><el-descriptions :column="1" border><el-descriptions-item :label="t('deviceSystemPage.deviceAsset.labels.subtype')">{{ labelSubtype(detail.subtype) }}</el-descriptions-item><el-descriptions-item :label="t('deviceSystemPage.deviceAsset.labels.system')">{{ detail.systemName }} / {{ systemMode(detail.systemMode) }}</el-descriptions-item><el-descriptions-item :label="t('deviceSystemPage.deviceAsset.labels.installSpace')">{{ detail.installSpaceName }}</el-descriptions-item><el-descriptions-item :label="t('deviceSystemPage.deviceAsset.labels.owner')">{{ detail.ownerTenantName||t('deviceSystemPage.deviceAsset.labels.platformOwner') }}</el-descriptions-item><el-descriptions-item :label="t('deviceSystemPage.deviceAsset.labels.manufacturerModel')">{{ detail.manufacturer||'--' }} / {{ detail.model||'--' }}</el-descriptions-item><el-descriptions-item :label="t('deviceSystemPage.deviceAsset.labels.serialNumber')">{{ detail.serialNumber||'--' }}</el-descriptions-item><el-descriptions-item :label="t('deviceSystemPage.deviceAsset.labels.accessMode')">{{ enumLabel('accessMode', detail.access?.accessMode, locale) }}</el-descriptions-item><el-descriptions-item :label="t('deviceSystemPage.deviceAsset.labels.protocol')">{{ detail.access?.protocolTemplate||'--' }}</el-descriptions-item><el-descriptions-item :label="t('deviceSystemPage.deviceAsset.labels.identifier')">{{ detail.access?.deviceIdentifier||'--' }}</el-descriptions-item><el-descriptions-item :label="t('deviceSystemPage.deviceAsset.labels.gatewayChannel')">{{ detail.access?.gatewayName||'--' }} / {{ detail.access?.channelCode||'--' }}</el-descriptions-item></el-descriptions><p class="mock-note">{{ t('deviceSystemPage.deviceAsset.detailNote') }}</p></template></el-drawer></template>
  </DsListPageShell>
</template>

<style scoped>
.header-actions,.row-actions{display:flex;align-items:center;gap:6px;white-space:nowrap}.header-actions{margin-left:auto}.asset-summary{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));margin:8px 16px;border:1px solid var(--color-border-default);border-radius:var(--radius-md);overflow:hidden}.asset-summary article{padding:6px 10px;border-right:1px solid var(--color-border-default)}.asset-summary article:last-child{border:0}.asset-summary span{display:block;color:var(--color-text-secondary);font-size:11px}.asset-summary strong{font-size:18px}.asset-summary .success{color:var(--color-success-default)}.asset-summary .warning{color:var(--color-warning-default)}
.hvac-control-deck{display:grid;grid-template-columns:210px 1fr;margin:0 16px 8px;border:1px solid var(--color-border-default);border-radius:var(--radius-md);background:var(--color-bg-surface);overflow:hidden}.selection-panel{display:flex;flex-direction:column;justify-content:space-between;gap:12px;padding:10px 12px;border-right:1px solid var(--color-border-default)}.selection-panel>div:first-child{display:flex;flex-direction:column;gap:2px}.selection-panel span,.command-group label,.command-note{color:var(--color-text-secondary);font-size:11px}.selection-panel strong{font-size:18px}.selection-stats{display:flex;align-items:center;gap:10px}.command-panel{display:flex;min-width:0;align-items:flex-end;gap:14px;padding:10px 12px}.command-group{display:flex;flex-direction:column;gap:5px}.temperature-control{display:grid;grid-template-columns:34px 56px 34px;align-items:center}.temperature-control strong{display:grid;height:32px;place-items:center;border-top:1px solid var(--color-border-default);border-bottom:1px solid var(--color-border-default);font-size:14px}.temperature-control :deep(.el-button){width:34px;margin:0;padding:0}.command-note{display:flex;min-width:180px;flex:1;align-items:center;gap:6px;line-height:1.45}.command-note span{display:-webkit-box;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2}.command-panel.disabled{opacity:.72}.command-readonly{display:flex;align-items:center;padding:12px;color:var(--color-text-secondary);font-size:12px}
